#include "main.h"
#include <stdio.h>

typedef void (*callback_t)(void);

callback_t user_callback;

void HAL_GPIO_EXTI_Callback(uint16_t GPIO_Pin) {
    if (GPIO_Pin == GPIO_PIN_0) {
        user_callback();
    }
}

int main(void) {
    HAL_Init();
    SystemClock_Config();
    MX_GPIO_Init();

    while (1) {
        HAL_Delay(1000);
    }
}
